(()=>{'use strict';const toggle=document.querySelector('.menu-toggle');const nav=document.querySelector('#main-nav');if(toggle&&nav){toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!open));nav.classList.toggle('is-open',!open);toggle.querySelector('.sr-only').textContent=open?'Apri il menu':'Chiudi il menu'});nav.addEventListener('click',event=>{if(event.target.closest('a')){toggle.setAttribute('aria-expanded','false');toggle.querySelector('.sr-only').textContent='Apri il menu';nav.classList.remove('is-open')}})}})();
(()=>{'use strict';
const root=document.querySelector('.longform');if(!root)return;
const fmt=(n,d=2)=>Number(n).toLocaleString('it-IT',{minimumFractionDigits:d,maximumFractionDigits:d});
const one=sel=>root.querySelector(sel);const all=sel=>[...root.querySelectorAll(sel)];
const dataUrl='/data/4-1-family-lottery.json';let data,origin=0,independent=false;
const labels=['Q1 · PIÙ BASSO','Q2','Q3','Q4','Q5 · PIÙ ALTO'];
fetch(dataUrl).then(r=>{if(!r.ok)throw Error('Dati non disponibili');return r.json()}).then(d=>{data=d;init()}).catch(()=>{const panel=one('#matrix-view');if(panel)panel.innerHTML='<p class="data-error">I dati del grafico non sono disponibili. Consulta la fonte principale nella nota metodologica.</p>'});
function init(){const urlOrigin=Number(new URL(location.href).searchParams.get('origine'));if(Number.isInteger(urlOrigin)&&urlOrigin>=1&&urlOrigin<=5)origin=urlOrigin-1;
renderTop();renderMatrix();renderDots();renderInd();renderDeciles();renderRobust();renderCountries();selectOrigin(origin,false);
all('.origin-picker [data-origin]').forEach(b=>b.addEventListener('click',()=>selectOrigin(Number(b.dataset.origin),true)));
all('.view-switch [data-view]').forEach(b=>b.addEventListener('click',()=>{const dots=b.dataset.view==='dots';all('.view-switch [data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));one('#matrix-view').hidden=dots;one('#dots-view').hidden=!dots;renderDots()}));
all('.ind-toggle [data-ind]').forEach(b=>b.addEventListener('click',()=>{independent=b.dataset.ind==='independent';all('.ind-toggle [data-ind]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderInd()}));
one('#simulate').addEventListener('click',()=>simulate(false));one('#instant-results').addEventListener('click',()=>simulate(true));
}
function selectOrigin(i,updateUrl){origin=Math.max(0,Math.min(4,i));all('.origin-picker [data-origin]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.origin)===origin)));const row=one(`#matrix-view tr[data-row="${origin}"]`);if(row){all('#matrix-view tr').forEach(r=>r.classList.toggle('is-selected',r===row));row.querySelector('button').setAttribute('aria-current','true');all('#matrix-view tr:not(.is-selected) button').forEach(b=>b.removeAttribute('aria-current'))}
const title=labels[origin].replace(' · PIÙ BASSO','').replace(' · PIÙ ALTO','');one('.origin-result p').innerHTML=`<strong>Hai scelto ${title}.</strong><br>Questa origine cambia le probabilità della posizione economica adulta.`;
if(updateUrl){const u=new URL(location.href);u.searchParams.set('origine',String(origin+1));history.replaceState({},'',u)}renderDots();}
function renderTop(){const vals=data.top20_by_parent_quintile.value;one('#top-chart').innerHTML=vals.map((v,i)=>`<div class="top-bar-row"><span class="bar-mobile-label">${labels[i]}</span><div class="bar-rail"><i style="--bar:${(v/36*100).toFixed(2)}%" class="${i===0||i===4?'bar-emphasis':''}"></i></div><strong>${fmt(v)}%</strong></div>`).join('');one('[data-metric="top-ratio"]').textContent=`${Math.round(data.top20_probability_ratio.value)}×`}
function renderMatrix(){const m=data.quintile_matrix.value;const heads=labels.map(x=>`<th scope="col">${x}</th>`).join('');one('#matrix-view').innerHTML=`<div class="matrix-scroll"><table class="mobility-table"><caption class="sr-only">Distribuzione percentuale dei figli per quintile di reddito dei genitori e dei figli adulti</caption><thead><tr><th scope="col">GENITORI ↓ / FIGLI →</th>${heads}</tr></thead><tbody>${m.map((r,i)=>`<tr data-row="${i}"><th scope="row"><button type="button" aria-label="Seleziona origine ${labels[i]}">${labels[i]}</button></th>${r.map((v,j)=>`<td><button type="button" class="heat-cell ${j===0||j===4?'edge-cell':''} ${v>=27?'heat-strong':''}" data-origin-row="${i}" aria-label="Origine ${labels[i]}, destinazione ${labels[j]}, ${fmt(v)} per cento" style="--heat:${Math.max(.12,v/34)}">${fmt(v)}<span>%</span></button></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
all('#matrix-view tbody th button').forEach(b=>b.addEventListener('click',()=>selectOrigin(Number(b.closest('tr').dataset.row),true)));
all('#matrix-view .heat-cell').forEach(b=>b.addEventListener('click',()=>selectOrigin(Number(b.dataset.originRow),true)));
all('#matrix-view tbody tr').forEach(tr=>tr.addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const n=Math.max(0,Math.min(4,Number(tr.dataset.row)+(e.key==='ArrowDown'?1:-1)));selectOrigin(n,true);one(`#matrix-view tr[data-row="${n}"] th button`).focus()}}));}
function renderDots(){if(!data)return;const row=data.quintile_matrix.value[origin];const counts=row.map(v=>Math.round(v));let delta=100-counts.reduce((a,b)=>a+b,0);while(delta!==0){const i=counts.indexOf(delta>0?Math.max(...counts):Math.min(...counts));counts[i]+=delta>0?1:-1;delta+=delta>0?-1:1}const dots=[];counts.forEach((n,q)=>{for(let k=0;k<n;k++)dots.push(`<i class="dot-q${q+1}" aria-hidden="true"></i>`)});one('#dot-grid').innerHTML=dots.join('');one('#dots-summary').textContent=`100 figli con origine ${labels[origin]} · valori arrotondati alla persona più vicina`;one('#dot-grid').setAttribute('aria-label',`100 persone: ${counts.map((n,i)=>`${n} nel ${labels[i]}`).join(', ')}`)}
function renderInd(){const m=data.quintile_matrix.value;const vals=independent?data.independence_benchmark.value:null;const display=m.map((r,i)=>`<div class="ind-row"><span>${labels[i]}</span><div>${r.map((v,j)=>{const shown=independent?vals[j]:v;return `<i class="ind-cell ${independent?'ind-flat':''}" style="--ind:${shown/34*100}%" aria-label="${fmt(shown)} per cento">${fmt(shown)}</i>`}).join('')}</div></div>`).join('');one('#ind-matrix').innerHTML=display;
const base=m[0][0],benchmark=data.independence_benchmark.value[0];one('#ind-insight').innerHTML=independent?`<span>OGNI ORIGINE → OGNI DESTINAZIONE</span><strong>${fmt(benchmark)}% <i>in ogni quintile</i></strong><span>Se origine e destinazione fossero indipendenti, ogni riga sarebbe piatta.</span>`:`<span>Q1 → Q1</span><strong>${fmt(base)}% <i>vs</i> ${fmt(benchmark)}%</strong><span>Restare nel quintile più basso è più frequente del benchmark di indipendenza.</span>`}
function renderDeciles(){const d=data.decile_transitions;const a=d.bottom10_to_top10.value,b=d.top10_to_top10.value;all('[data-metric="bottom10Top10"],[data-metric="top10Top10"]').forEach(el=>{const v=el.dataset.metric==='bottom10Top10'?a:b;el.textContent=`${fmt(v)}%`;el.nextElementSibling.querySelector('i').style.width=`${v/30*100}%`});one('[data-metric="decile-ratio"]').textContent=`OLTRE ${Math.floor(d.ratio.value)} VOLTE`}
function simulate(instant){const n=Number(one('#sim-count').value);const probs=data.quintile_matrix.value[origin];const result=[0,0,0,0,0];const total=probs.reduce((a,b)=>a+b,0);for(let k=0;k<n;k++){let x=Math.random()*total;for(let j=0;j<5;j++){x-=probs[j];if(x<=0){result[j]++;break}}}one('#sim-results').innerHTML=`<p class="sim-result-title">${n.toLocaleString('it-IT')} ${n===1?'estrazione':'estrazioni'} · origine ${labels[origin]}</p><div class="sim-result-bars">${result.map((v,i)=>`<div><span>${labels[i]}</span><i><b style="width:${n?v/n*100:0}%"></b></i><strong>${v}${n===1?'':` · ${fmt(v/n*100,1)}%`}</strong></div>`).join('')}</div><p class="sim-footnote">${instant?'Risultati mostrati senza animazione. ':''}Campione casuale: la prossima esecuzione darà conteggi diversi.</p>`}
function renderRobust(){const meta=data.robustness_metadata;one('#robust-grid').innerHTML=data.robustness.map((r,i)=>`<article class="robust-card ${r.is_model_adjusted?'is-adjusted':''}"><span class="eyebrow">0${i+1} / ${r.is_model_adjusted?'CORREZIONE':'RIFERIMENTO'}</span><h3>${r.label}</h3><div class="robust-values"><div><small>RANK-RANK SLOPE</small><strong>${fmt(r.rrs,3)}</strong></div><div><small>BOTTOM → TOP 20%</small><strong>${fmt(r.bottomToTop,1)}%</strong></div></div><p>${r.kind}</p><a href="${meta.source_url}" target="_blank" rel="noreferrer">${r.source} ↗</a></article>`).join('')}
function renderCountries(){const countries=data.international_comparison;one('#country-chart').innerHTML=countries.map((c,i)=>`<div class="country-row"><span>${c.country}</span><div><i style="--country:${c.value/0.36*100}%" class="country-${i}"></i></div><strong>${fmt(c.value,2)}</strong></div>`).join('');one('[data-metric="rank-slope"]').textContent=fmt(data.rank_rank_slope.value);one('[data-metric="rank-r2"]').textContent=`≈ ${fmt(data.rank_r2.value,2)}`;const q=data.dispersion_quantiles.value;const low=one('[data-quantile="low"]'),high=one('[data-quantile="high"]');[[low,q[0]],[high,q[1]]].forEach(([row,v])=>{row.querySelector('span i').textContent=`${v.parent_percentile}°`;row.querySelector('.range-rail>i').style.setProperty('--to',`${v.child_percentile}%`);row.querySelector('.range-rail b').textContent=`${v.share}% dei figli ${v.tail==='above'?'sopra':'sotto'} il ${v.child_percentile}°`});one('[data-metric="wealth-correlation"]').textContent=fmt(data.wealth_persistence.value.correlation_average,2);one('[data-metric="wealth-age-adjusted"]').textContent=fmt(data.wealth_persistence.value.age_adjusted,2)}
})();
